import type { CodePuzzle } from "@/lib/types";

/**
 * Block-based code puzzles. Each pattern has at least one "core" puzzle and
 * some patterns have "twist" or "diagnostic" variants for replay value.
 *
 * Every puzzle carries:
 *  - `hints`: a 5-rung progressive ladder (goal → first move → next block →
 *    misplacement → near-complete reveal)
 *  - `structuralChecks`: per-block anchors the checker uses to produce
 *    actionable wrong-answer feedback instead of a generic "try again"
 *  - `intent`: a one-line "why this shape matters" blurb shown above the pool
 *
 * Teaching philosophy: the user is building SHAPE first, syntax second. A
 * stuck user should always be able to keep moving via the hint ladder. No
 * dead ends, no shame.
 */
