export const PUZZLE_MAP: Record<string, CodePuzzle> = Object.fromEntries(
  CODE_PUZZLES.map((p) => [p.id, p]),
);

export const PUZZLES_BY_PATTERN: Record<string, CodePuzzle[]> =
  CODE_PUZZLES.reduce(
    (acc, p) => {
      (acc[p.patternId] ||= []).push(p);
      return acc;
    },
    {} as Record<string, CodePuzzle[]>,
  );

/**
 * Problem → puzzle lookup. Each problem has at most one authored puzzle.
 * The canonical UX path: build a session for a problem, get the exact block
 * layout for that problem — never a pattern-relabelled substitute.
 */
export const PUZZLE_BY_PROBLEM: Record<string, CodePuzzle> = Object.fromEntries(
  CODE_PUZZLES.filter((p) => p.problemId).map((p) => [p.problemId, p]),
);

export function puzzleForProblem(problemId: string): CodePuzzle | undefined {
  return PUZZLE_BY_PROBLEM[problemId];
}

/**
 * True if a problem has a hand-authored canonical puzzle. Used by the plan
 * builder to prefer problems we can actually solve in the mission flow.
 */
export function hasPuzzle(problemId: string): boolean {
  return problemId in PUZZLE_BY_PROBLEM;
}

export function puzzleVariants(patternId: string): CodePuzzle[] {
  return PUZZLES_BY_PATTERN[patternId] || [];
}
